import Foundation

public enum VehicleDriveLayout:String,Codable,Sendable { case frontEngineRWD, frontEngineAWD, rearEngineRWD, rearEngineAWD, midEngineRWD }
public enum VehicleTransmissionFamily:String,Codable,Sendable { case manual4, manual5, manual6, automatic3, automatic4, dct7, sequential6, prototypeDCT }
public enum VehicleSteeringFamily:String,Codable,Sendable { case recirculatingBall, hydraulicRack, electricRack, motorsportRack }
public enum VehicleBodyFamily:String,Codable,Sendable { case classicFastback, classicGrandTourer, modernCoupe, widebodyTrackCoupe, experimentalGT }

/// Executable fictional production calibration. Exact historical/OEM values remain research-gated.
