 public var trackRearM:Double
 public var cgHeightM:Double
 public var frontWeightFraction:Double
 public var ratedPowerKW:Double
 public var ratedTorqueNm:Double
 public var redlineRPM:Double
 public var finalDrive:Double
 public var tireSectionFrontMm:Double
 public var tireSectionRearMm:Double
 public var aeroDownforceScale01:Double
 public var brakeThermalCapacity01:Double
 public var coolingCapacity01:Double
 public var chassisRigidity01:Double
 public var serviceComplexity01:Double
 public var diagnosticTechnology:DiagnosticTechnology
 public var signatureFailureMechanisms:[String]
 public var serviceHighlights:[String]
 public var visualIdentity:[String]
 public var researchGates:[String]
 public init(id:String,displayName:String,generationId:String,modelYearBand:String,body:VehicleBodyFamily,drive:VehicleDriveLayout,transmission:VehicleTransmissionFamily,steering:VehicleSteeringFamily,massKg:Double,wheelbaseM:Double,trackFrontM:Double,trackRearM:Double,cgHeightM:Double,frontWeightFraction:Double,ratedPowerKW:Double,ratedTorqueNm:Double,redlineRPM:Double,finalDrive:Double,tireSectionFrontMm:Double,tireSectionRearMm:Double,aeroDownforceScale01:Double,brakeThermalCapacity01:Double,coolingCapacity01:Double,chassisRigidity01:Double,serviceComplexity01:Double,diagnosticTechnology:DiagnosticTechnology,signatureFailureMechanisms:[String],serviceHighlights:[String],visualIdentity:[String],researchGates:[String]) { self.id=id;self.displayName=displayName;self.generationId=generationId;self.modelYearBand=modelYearBand;self.body=body;self.drive=drive;self.transmission=transmission;self.steering=steering;self.massKg=massKg;self.wheelbaseM=wheelbaseM;self.trackFrontM=trackFrontM;self.trackRearM=trackRearM;self.cgHeightM=cgHeightM;self.frontWeightFraction=frontWeightFraction;self.ratedPowerKW=ratedPowerKW;self.ratedTorqueNm=ratedTorqueNm;self.redlineRPM=redlineRPM;self.finalDrive=finalDrive;self.tireSectionFrontMm=tireSectionFrontMm;self.tireSectionRearMm=tireSectionRearMm;self.aeroDownforceScale01=aeroDownforceScale01;self.brakeThermalCapacity01=brakeThermalCapacity01;self.coolingCapacity01=coolingCapacity01;self.chassisRigidity01=chassisRigidity01;self.serviceComplexity01=serviceComplexity01;self.diagnosticTechnology=diagnosticTechnology;self.signatureFailureMechanisms=signatureFailureMechanisms;self.serviceHighlights=serviceHighlights;self.visualIdentity=visualIdentity;self.researchGates=researchGates }
 public var geometry:VehicleGeometry { var g=VehicleGeometry(); g.massKg=massKg; g.wheelbaseM=wheelbaseM; g.cgHeightM=cgHeightM; g.frontTrackM=trackFrontM; g.rearTrackM=trackRearM; g.frontStaticWeightFraction=frontWeightFraction; return g }
}

